//! 32-byte swap secret and its SHA-256 commitment.
//!
//! Both bridge legs commit to `PreimageHash = SHA256(Preimage)`. The
//! preimage is generated by the swap's *initiating* maker (Alice in
//! `CROSS_CHAIN_SWAP.md`) and revealed by whoever spends the first leg.
//! Never serialise [`Preimage`] in any wire format; only [`PreimageHash`]
//! belongs on the relay or in the typed swap envelope.

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};

/// 32-byte swap secret. **Never serialise this**; only the maker holds it
/// until it is revealed on-chain.
#[derive(Debug, Clone)]
pub struct Preimage(pub [u8; 32]);

impl Preimage {
    /// Draw a fresh random preimage.
    pub fn random() -> Self {
        use rand::RngCore;
        let mut bytes = [0u8; 32];
        rand::thread_rng().fill_bytes(&mut bytes);
        Self(bytes)
    }

    /// Parse a preimage from 64 hex chars.
    pub fn from_hex(s: &str) -> Result<Self> {
        let bytes = hex::decode(s.trim()).context("decoding preimage hex")?;
        let arr: [u8; 32] = bytes
            .try_into()
            .map_err(|_| anyhow::anyhow!("preimage must be 32 bytes"))?;
        Ok(Self(arr))
    }

    /// 64-char lowercase hex.
    pub fn to_hex(&self) -> String {
        hex::encode(self.0)
    }

    /// The hash commitment that goes into both covenant legs.
    pub fn hash(&self) -> PreimageHash {
        use sha2::{Digest, Sha256};
        let digest = Sha256::digest(self.0);
        let mut out = [0u8; 32];
        out.copy_from_slice(&digest);
        PreimageHash(out)
    }
}

/// `SHA256(Preimage)` — the 32-byte commitment both covenant legs share.
/// This is the only preimage-related value that ever leaves the maker's
/// machine before the swap is revealed.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(transparent)]
pub struct PreimageHash(#[serde(with = "hex_array")] pub [u8; 32]);

impl PreimageHash {
    pub fn to_hex(&self) -> String {
        hex::encode(self.0)
    }

    pub fn from_hex(s: &str) -> Result<Self> {
        let bytes = hex::decode(s.trim()).context("decoding preimage hash hex")?;
        let arr: [u8; 32] = bytes
            .try_into()
            .map_err(|_| anyhow::anyhow!("preimage hash must be 32 bytes"))?;
        Ok(Self(arr))
    }

    /// True iff `SHA256(candidate) == self`.
    pub fn matches(&self, candidate: &Preimage) -> bool {
        candidate.hash() == *self
    }
}

mod hex_array {
    use serde::{Deserialize, Deserializer, Serializer};

    pub fn serialize<S>(bytes: &[u8; 32], s: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        s.serialize_str(&hex::encode(bytes))
    }

    pub fn deserialize<'de, D>(d: D) -> Result<[u8; 32], D::Error>
    where
        D: Deserializer<'de>,
    {
        let s = String::deserialize(d)?;
        let bytes = hex::decode(&s).map_err(serde::de::Error::custom)?;
        bytes
            .try_into()
            .map_err(|_| serde::de::Error::custom("expected 32 bytes hex"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn preimage_hash_roundtrips() {
        let p = Preimage::random();
        let h = p.hash();
        assert!(h.matches(&p));
        let p2 = Preimage::from_hex(&p.to_hex()).unwrap();
        assert_eq!(p.0, p2.0);
        assert_eq!(h.to_hex().len(), 64);
    }

    #[test]
    fn preimage_hash_serde_is_just_a_hex_string() {
        let p = Preimage([7u8; 32]);
        let h = p.hash();
        let json = serde_json::to_string(&h).unwrap();
        assert!(json.starts_with('"') && json.ends_with('"'));
        let back: PreimageHash = serde_json::from_str(&json).unwrap();
        assert_eq!(back, h);
    }

    #[test]
    fn preimage_hash_rejects_wrong_preimage() {
        let p = Preimage::random();
        let h = p.hash();
        let bad = Preimage::random();
        assert!(!h.matches(&bad));
    }
}
